:root {
  --background: #fffaf6;
  --foreground: #514450;
  --card: #fff;
  --card-foreground: #514450;
  --popover: #fff;
  --popover-foreground: #514450;
  --primary: #df7096;
  --primary-foreground: #fff;
  --secondary: #fff0f3;
  --secondary-foreground: #a25070;
  --muted: #f5eeed;
  --muted-foreground: #867883;
  --accent: #e7f4ff;
  --accent-foreground: #4d7296;
  --destructive: #c4536b;
  --border: #ebd9df;
  --input: #e7c7d4;
  --ring: #db88a6;
  --radius: 1rem;
  --ink: #514450;
  --pink: #de7397;
  --soft-pink: #fff0f4;
  --blue: #649dcb;
  --cream: #fffaf3;
  --muted-ink: #8a7985;
  --font-sans: "Arial Rounded MT Bold", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
}

* {
  box-sizing: border-box;
}

html,body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  font-family: var(--font-sans);
  color: var(--ink);
  background: #f8eaf0;
}

button,input {
  font: inherit;
}

button {
  -webkit-tap-highlight-color: transparent;
  cursor: pointer;
  touch-action: manipulation;
}

button:disabled {
  cursor: default;
}

button:focus-visible,input:focus-visible {
  outline-offset: 4px;
  outline: 3px solid #769fc9;
}

h1:focus {
  outline: none;
}

::selection {
  color: #954a69;
  background: #ffe2ed;
}

.invitation-world {
  min-width: 0;
  height: var(--invitation-height,100dvh);
  background: radial-gradient(at 12% 18%,#fef7d5,#0000 40%),radial-gradient(at 88% 88%,#e0f2ff,#0000 45%),#fbeaf0;
  place-items: center;
  padding: 16px;
  display: grid;
  overflow: hidden;
}

.invitation-app {
  width: min(580px,100%);
  height: min(920px, calc(var(--invitation-height,100dvh) - 32px));
  background: var(--cream);
  border: 2px solid #fff;
  border-radius: 31px;
  grid-template-rows: 59px 4px minmax(0,1fr) 28px;
  min-height: 0;
  display: grid;
  overflow: hidden;
  box-shadow: 0 22px 75px #a67b9626,0 3px #edd6df;
}

.app-header {
  background: #fffaf8;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  padding: 0 14px;
  display: flex;
}

.app-wordmark {
  color: #8c697e;
  white-space: nowrap;
  align-items: center;
  gap: 7px;
  font-size: 15px;
  font-weight: 800;
  display: flex;
}

.app-wordmark svg {
  color: #df7ca0;
}

.icon-button {
  color: #a3758c;
  border-radius: 50%;
  flex-shrink: 0;
  width: 43px;
  height: 43px;
  padding: 0;
}

.icon-button svg {
  width: 21px;
  height: 21px;
}

.icon-button:disabled {
  opacity: 0;
}

.sound-control {
  color: #8d8196;
}

.story-progress {
  background: #fffaf8;
  gap: 4px;
  padding: 0 27px;
  display: flex;
}

.story-progress span {
  background: #f0e3e7;
  border-radius: 9px;
  flex: 1;
  transition: background .3s;
}

.story-progress span.active {
  background: #e5a1b9;
}

.story-stage {
  background: radial-gradient(at 100% 0,#fff0f2,#0000 58%),#fffaf4;
  min-height: 0;
  position: relative;
  overflow: hidden;
  container-type: size;
}

.app-footer {
  color: #ae98a6;
  letter-spacing: .08em;
  background: #fffaf8;
  justify-content: space-between;
  align-items: center;
  padding: 0 23px;
  font-size: 10px;
  font-weight: 700;
  display: flex;
}

.step-page {
  text-align: center;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 16px;
  width: 100%;
  height: 100%;
  min-height: 0;
  padding: 24px 34px;
  animation: .35s both pageIn;
  display: flex;
}

.step-page h1 {
  letter-spacing: -.055em;
  overflow-wrap: anywhere;
  margin: 0;
  font-size: clamp(31px,4.8cqh,43px);
  font-weight: 900;
  line-height: 1.2;
}

.step-page h1>span {
  color: var(--pink);
}

.step-label {
  color: #b27d96;
  letter-spacing: .025em;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 800;
  display: flex;
}

.tiny-eyebrow {
  color: #b68a9f;
  letter-spacing: .16em;
  font-size: 11px;
  font-weight: 800;
}

.lead {
  color: #8c7482;
  margin: 0;
  font-size: 18px;
  font-weight: 650;
  line-height: 1.65;
}

.lead strong {
  color: #756075;
  font-weight: 850;
}

.primary-action,.secondary-action {
  border-radius: 17px;
  width: 100%;
  height: auto;
  min-height: 56px;
  padding: 15px 17px;
  font-size: 17px;
  font-weight: 850;
  line-height: 1.25;
}

.primary-action {
  color: #fff;
  background: #df789b;
  border: 1px solid #d1678d;
  box-shadow: 0 4px #ba5c81,inset 0 1px #ffffff52;
}

.primary-action:active {
  transform: translateY(2px);
  box-shadow: 0 2px #ba5c81;
}

.primary-action:disabled {
  opacity: .45;
}

.primary-action>svg,.secondary-action>svg {
  width: 20px;
  height: 20px;
}

.secondary-action {
  color: #a46683;
  background: #fff4f7;
  border: 1px solid #eac7d6;
  box-shadow: 0 3px #efdae3;
}

.text-action {
  color: #987185;
  height: auto;
  min-height: 36px;
  padding: 6px 8px;
  font-size: 14px;
  font-weight: 750;
}

.hero-icon {
  color: #d789a7;
  background: #ffe9f1;
  border-radius: 28px;
  place-items: center;
  width: 86px;
  height: 86px;
  display: grid;
  transform: rotate(-7deg);
  box-shadow: 0 5px #f4d5e2;
}

.hero-icon svg {
  stroke-width: 1.6px;
  width: 38px;
  height: 38px;
}

.round-pill {
  color: #ac7e6b;
  background: #fff0e9;
  border-radius: 30px;
  justify-content: center;
  align-items: center;
  gap: 7px;
  margin: 0;
  padding: 10px 16px;
  font-size: 16px;
  font-weight: 800;
  display: flex;
}

.sky-opening {
  background: linear-gradient(#dff2fd 0%,#f1f8ff 50%,#fff7ed 100%);
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

.sky-cloud {
  color: #ffffffbd;
  position: absolute;
}

.sky-cloud svg {
  fill: currentColor;
  stroke-width: .5px;
  width: 100%;
  height: 100%;
}

.cloud-one {
  width: 170px;
  height: 100px;
  top: 16%;
  left: -24px;
  transform: rotate(-5deg);
}

.cloud-two {
  width: 175px;
  height: 100px;
  top: 43%;
  right: -20px;
  transform: rotate(7deg);
}

.cloud-three {
  opacity: .6;
  width: 128px;
  height: 76px;
  bottom: 13%;
  left: 16%;
}

.sky-intro {
  z-index: 2;
  text-align: center;
  transition: opacity .2s;
  position: absolute;
  top: 7%;
  left: 18px;
  right: 18px;
}

.sky-intro h1 {
  letter-spacing: -.055em;
  color: #6d7194;
  margin: 10px 0 0;
  font-size: clamp(31px,4.7cqh,42px);
  font-weight: 900;
  line-height: 1.25;
}

.sky-intro h1 span {
  color: #d58aa5;
}

.balloon-target {
  z-index: 3;
  color: #ad6588;
  width: min(430px,87%);
  height: 55%;
  box-shadow: none;
  border: 0;
  border-radius: 50%;
  padding: 0;
  animation: 3s ease-in-out infinite balloonFloat;
  position: absolute;
  top: 27%;
  left: 50%;
  transform: translate(-50%);
  background: 0 0!important;
}

.balloon-art {
  background: url(data:image/png;base64,) 50%/contain no-repeat;
  width: 100%;
  height: 100%;
  display: block;
}

.tap-label {
  background: #fffffff2;
  border-radius: 28px;
  align-items: center;
  gap: 4px;
  padding: 9px 14px;
  font-size: 16px;
  font-weight: 850;
  display: flex;
  position: absolute;
  top: 50%;
  right: 7%;
  transform: rotate(8deg);
  box-shadow: 0 5px 18px #a6789430;
}

.sky-bottom {
  z-index: 4;
  text-align: center;
  position: absolute;
  bottom: 6%;
  left: 12px;
  right: 12px;
}

.sky-bottom>p {
  color: #a67b8d;
  margin: 0;
  font-size: 17px;
  font-weight: 700;
}

.resume-actions {
  justify-content: center;
  gap: 10px;
  margin-top: 9px;
  display: flex;
}

.resume-actions button {
  color: #9a7c92;
  text-underline-offset: 4px;
  min-height: 36px;
  font-size: 14px;
  font-weight: 750;
  text-decoration: underline;
}

.popped .balloon-target {
  animation: .2s forwards balloonPop;
}

.popped .sky-intro,.popped .sky-bottom {
  opacity: 0;
  pointer-events: none;
}

.falling-letter {
  z-index: 5;
  color: #d992ac;
  background: #fffaf1;
  border: 2px solid #edc5d4;
  border-radius: 10px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 4px;
  width: 155px;
  height: 108px;
  animation: 2s ease-in-out forwards letterFall;
  display: flex;
  position: absolute;
  top: 30%;
  left: 50%;
  box-shadow: 0 15px 35px #b28ca329;
}

.falling-letter svg {
