@keyframes pageIn {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes balloonFloat {
  0%,to {
    transform: translate(-50%)rotate(-3deg);
  }
  50% {
    transform: translate(-50%,-13px)rotate(3deg);
  }
}

@keyframes balloonPop {
  0% {
    opacity: 1;
    transform: translate(-50%)scale(1);
  }
  70% {
    opacity: .8;
    transform: translate(-50%)scale(1.12);
  }
  to {
    opacity: 0;
    transform: translate(-50%)scale(1.22);
  }
}

@keyframes sparklePop {
  0% {
    opacity: 1;
    transform: scale(.7);
  }
  to {
    opacity: 0;
    transform: scale(1.5)translateY(-35px);
  }
}

@keyframes letterFall {
  0% {
    opacity: 0;
    transform: translate(-50%,-10px)rotate(-16deg)scale(.65);
  }
  15% {
    opacity: 1;
    transform: translate(-63%,25px)rotate(-16deg)scale(.8);
  }
  43% {
    transform: translate(-30%,85px)rotate(12deg)scale(1);
  }
  71% {
    transform: translate(-62%,135px)rotate(-9deg)scale(1.15);
  }
  to {
    opacity: 1;
    transform: translate(-50%,165px)rotate(0)scale(1.35);
  }
}

@keyframes letterUnfold {
  0% {
    opacity: .5;
    transform: rotateX(-68deg)scale(.8);
  }
  to {
    opacity: 1;
    transform: rotateX(0)scale(1);
  }
}

@keyframes mistAcross {
  0% {
    opacity: 0;
    transform: translate(0);
  }
  25% {
    opacity: .9;
  }
  80% {
    opacity: .5;
  }
  to {
    opacity: 0;
    transform: translate(260%);
  }
}

@keyframes guestWiggle {
  0%,to {
    transform: rotate(-3deg)translateY(0);
  }
  25% {
    transform: rotate(1deg)translateY(-3px);
  }
  50% {
    transform: rotate(3deg)translateY(0);
  }
  75% {
    transform: rotate(-1deg)translateY(-2px);
  }
}

@keyframes birthdayBounce {
  0%,to {
    transform: translateY(0)rotate(-2deg);
  }
  50% {
    transform: translateY(-4px)rotate(2deg);
  }
}

@keyframes openLeftDoor {
  to {
    opacity: .15;
    transform: rotateY(-108deg);
  }
}

@keyframes openRightDoor {
  to {
    opacity: .15;
    transform: rotateY(108deg);
  }
}

@keyframes confettiFall {
  0% {
    transform: translateY(-10px)rotate(0);
  }
  to {
    transform: translateY(420px)rotate(480deg);
  }
}

