    font-size: 17px;
  }
  .quiz-dress-page h1 {
    font-size: 28px;
  }
  .quiz-dress-page .primary-action {
    font-size: 15px;
  }
  .ticket-choice strong {
    font-size: 18px;
  }
}

@media (height<=650px) {
  .activity-page,.familiarity-page,.quiz-dress-page {
    gap: 8px;
  }
  .survey-options {
    gap: 9px;
  }
  .survey-option {
    padding-block: 12px;
  }
  .familiarity-options .survey-option {
    padding-block: 10px;
  }
  .survey-option>span {
    gap: 3px;
  }
  .survey-option small {
    line-height: 1.35;
  }
  .familiarity-page h1,.activity-page h1,.quiz-dress-page h1 {
    font-size: 27px;
  }
  .familiarity-page .step-label,.quiz-dress-page .step-label {
    font-size: 14px;
  }
  .survey-help {
    padding: 8px;
    line-height: 1.4;
  }
  .team-preview {
    gap: 4px;
    min-height: 68px;
    padding: 7px 5px;
  }
  .team-preview-grid {
    gap: 9px;
  }
  .team-preview .color-dots i {
    border-width: 2px;
    width: 26px;
    height: 26px;
  }
  .day-of-note {
    padding-block: 9px;
  }
  .winter-dress-page h1 {
    font-size: 35px;
    display: block;
  }
  .winter-dress-page .winter-dress-card {
    padding-block: 15px;
  }
  .winter-dress-page .color-dots i {
    width: 39px;
    height: 39px;
  }
  .winter-dress-page .winter-dress-card>p>strong {
    font-size: 20px;
  }
  .ticket-team-note {
    padding: 9px 8px;
  }
  .ticket-team-note p {
    margin-top: 5px;
    line-height: 1.35;
  }
}

.familiarity-page h1 {
  font-size: clamp(26px,6.1cqw,35px);
}

.route-page {
  gap: clamp(9px,2cqh,18px);
}

@media (height<=700px) {
  .route-page {
    gap: 10px;
  }
  .route-options {
    gap: 11px;
  }
  .route-option {
    min-height: 76px;
    padding: 12px 14px;
  }
  .route-page .lead {
    font-size: 16px;
  }
}

@media (height<=650px) {
  .route-page>.lead {
    display: none;
  }
}

